# 82_tables_fig6_random.R: Figure 6 random-split summaries from 81_cv_interactions_random.R (no refitting).
#   delta_D2 = D2_interaction - D2_additive on identical training/test sets of the same split (held-out = test sites; in-sample = training sets). Summary over the 30 splits: median, central 95% interval
#   (2.5/97.5% quantiles), min, max, number of splits with delta > 0. No fits removed (non-converged fits are flagged and counted). Intervals are variability across non-independent splits, not significance tests.
#   closure: the coherent prediction satisfies C + O + H = 1 (C = 1 - total dissimilarity, O = occupancy-associated, H = heterogeneity) to numerical precision when closure_RMSE ~ 0.
suppressMessages({library(dplyr); library(tidyr)}); OUT <- "revision_random/tables"; qf <- function(x, p) unname(quantile(x, p, type = 7))
for (pool in c("shared", "full")) { M <- read.csv(file.path(OUT, sprintf("rv6_metrics_%s.csv", pool))); key <- c("group", "pool", "order", "rsplit", "component", "split"); stopifnot(!anyDuplicated(M[c(key, "model")]))
  A <- M |> filter(model == "additive") |> select(all_of(key), D2_add = D2, conv_add = converged); I <- M |> filter(model != "additive") |> select(all_of(key), model, variant, penalty, D2_int = D2, conv_int = converged) |> inner_join(A, by = key); stopifnot(nrow(I) == sum(M$model != "additive"))
  P <- I |> mutate(delta_D2 = D2_int - D2_add, any_nonconverged = !(conv_add & conv_int)); write.csv(P, file.path(OUT, sprintf("rv6_paired_splits_%s.csv", pool)), row.names = FALSE)
  Ps <- P |> group_by(group, pool, order, component, split, model, variant, penalty) |> summarise(median = median(delta_D2), q025 = qf(delta_D2, .025), q975 = qf(delta_D2, .975), min = min(delta_D2), max = max(delta_D2), mean = mean(delta_D2), n_splits = n(), n_splits_positive = sum(delta_D2 > 0), n_nonconverged_pairs = sum(any_nonconverged), .groups = "drop"); write.csv(Ps, file.path(OUT, sprintf("rv6_paired_summary_%s.csv", pool)), row.names = FALSE)
  # absolute performance of every model (held-out and training D2)
  Pm <- M |> group_by(group, pool, order, component, split, model, variant, penalty) |> summarise(median = median(D2), q025 = qf(D2, .025), q975 = qf(D2, .975), mean = mean(D2), n_splits = n(), .groups = "drop"); write.csv(Pm, file.path(OUT, sprintf("rv6_performance_%s.csv", pool)), row.names = FALSE)
  # TP-only vs all-predictor interaction at matched penalty
  T <- M |> filter(variant %in% c("interaction_all", "interaction_TP")) |> select(all_of(key), variant, penalty, D2) |> pivot_wider(names_from = variant, values_from = D2) |> mutate(delta = interaction_TP - interaction_all) |>
    group_by(group, pool, order, component, split, penalty) |> summarise(median = median(delta), q025 = qf(delta, .025), q975 = qf(delta, .975), n_splits = n(), n_splits_positive = sum(delta > 0), .groups = "drop"); write.csv(T, file.path(OUT, sprintf("rv6_tp_only_vs_all_%s.csv", pool)), row.names = FALSE)
  Cv <- M |> distinct(group, pool, order, rsplit, model, variant, penalty, converged, share_identified) |> group_by(group, pool, order, model, variant, penalty) |> summarise(n_fits = n(), n_converged = sum(converged), n_nonconverged = sum(!converged), n_share_not_identified = sum(!share_identified), .groups = "drop"); write.csv(Cv, file.path(OUT, sprintf("rv6_convergence_%s.csv", pool)), row.names = FALSE)
  cl <- M |> distinct(group, pool, order, rsplit, model, split, closure_RMSE, evaluated_fraction) |> group_by(group, pool, split) |> summarise(max_closure_RMSE = max(closure_RMSE, na.rm = TRUE), min_evaluated_fraction = min(evaluated_fraction, na.rm = TRUE), n = n(), .groups = "drop"); write.csv(cl, file.path(OUT, sprintf("rv6_closure_%s.csv", pool)), row.names = FALSE)
  cat("==", pool, "max closure RMSE:", max(cl$max_closure_RMSE), "\n"); print(as.data.frame(Ps |> filter(split == "test", component == "total", variant %in% c("interaction_TP"), abs(penalty - 1e-6) < 1e-12) |> select(group, order, median, q025, q975, n_splits_positive)), digits = 3)
  print(as.data.frame(Ps |> filter(split == "test", component == "total", variant %in% c("interaction_all"), abs(penalty - 1e-6) < 1e-12) |> select(group, order, median, q025, q975, n_splits_positive)), digits = 3) }
